1	/*
2	 * Hot-loop detector plugin.
3	 *
4	 * Detects loops by observing backward TB transitions: when the next
5	 * executed translation block starts at a PC strictly less than the
6	 * last instruction PC of the previously executed TB, we treat that
7	 * pair (header_pc=current_tb_start, tail_pc=last_insn_of_prev_tb) as
8	 * a loop edge and bump its iteration count.
9	 *
10	 * Output (at exit, sorted by iteration count desc):
11	 *   start_pc, end_pc, iterations
12	 *
13	 * Copyright (C) 2026
14	 * License: GNU GPL, version 2 or later.
15	 *   See the COPYING file in the top-level directory.
16	 */
17	#include <inttypes.h>
18	#include <stdlib.h>
19	#include <string.h>
20	#include <stdio.h>
21	#include <glib.h>
22	
23	#include <qemu-plugin.h>
24	
25	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
26	
27	static GMutex lock;              /* guards the shared loops table only */
28	static GHashTable *loops;        /* key: (start<<1)^end -> LoopEdge* */
29	static struct qemu_plugin_scoreboard *vcpu_sb;  /* per-cpu VCPUState */
30	static guint64 limit = 50;       /* max rows printed */
31	static guint64 min_iters = 1;    /* rows with count < min_iters are dropped */
32	
33	typedef struct {
34	    uint64_t start_pc;           /* loop header (target of backward branch) */
35	    uint64_t end_pc;             /* tail: last insn pc of preceding TB */
36	    uint64_t count;              /* iterations observed */
37	} LoopEdge;
38	
39	typedef struct {
40	    uint64_t last_tail_pc;       /* PC of last insn of previously executed TB */
41	    bool     valid;
42	} VCPUState;
43	
44	typedef struct {
45	    uint64_t tb_start;
46	    uint64_t tb_last_insn_pc;
47	} TBInfo;
48	
49	static guint loop_hash(gconstpointer p)
50	{
51	    const LoopEdge *e = p;
52	    return (guint)(e->start_pc * 1315423911u ^ e->end_pc);
53	}
54	
55	static gboolean loop_equal(gconstpointer a, gconstpointer b)
56	{
57	    const LoopEdge *x = a, *y = b;
58	    return x->start_pc == y->start_pc && x->end_pc == y->end_pc;
59	}
60	
61	static gint cmp_count_desc(gconstpointer a, gconstpointer b)
62	{
63	    const LoopEdge *x = a, *y = b;
64	    if (x->count == y->count) {
65	        return 0;
66	    }
67	    return x->count > y->count ? -1 : 1;
68	}
69	
70	static void vcpu_tb_exec(unsigned int cpu_index, void *udata)
71	{
72	    TBInfo *tbi = (TBInfo *)udata;
73	    VCPUState *st = qemu_plugin_scoreboard_find(vcpu_sb, cpu_index);
74	
75	    if (st->valid && tbi->tb_start <= st->last_tail_pc) {
76	        LoopEdge probe = {
77	            .start_pc = tbi->tb_start,
78	            .end_pc   = st->last_tail_pc,
79	        };
80	        g_mutex_lock(&lock);
81	        LoopEdge *e = g_hash_table_lookup(loops, &probe);
82	        if (!e) {
83	            e = g_new0(LoopEdge, 1);
84	            e->start_pc = probe.start_pc;
85	            e->end_pc   = probe.end_pc;
86	            g_hash_table_insert(loops, e, e);
87	        }
88	        e->count++;
89	        g_mutex_unlock(&lock);
90	    }
91	
92	    st->last_tail_pc = tbi->tb_last_insn_pc;
93	    st->valid = true;
94	}
95	
96	static void vcpu_tb_trans(G_GNUC_UNUSED qemu_plugin_id_t id,
97	                          struct qemu_plugin_tb *tb)
98	{
99	    size_t n = qemu_plugin_tb_n_insns(tb);
100	    if (n == 0) {
101	        return;
102	    }
103	    struct qemu_plugin_insn *last = qemu_plugin_tb_get_insn(tb, n - 1);
104	
105	    TBInfo *tbi = g_new0(TBInfo, 1);
106	    tbi->tb_start = qemu_plugin_tb_vaddr(tb);
107	    tbi->tb_last_insn_pc = qemu_plugin_insn_vaddr(last);
108	
109	    qemu_plugin_register_vcpu_tb_exec_cb(tb, vcpu_tb_exec,
110	                                         QEMU_PLUGIN_CB_NO_REGS,
111	                                         (void *)tbi);
112	}
113	
114	static void plugin_exit(G_GNUC_UNUSED qemu_plugin_id_t id, G_GNUC_UNUSED void *p)
115	{
116	    g_autoptr(GString) report = g_string_new("");
117	    GList *vals = g_hash_table_get_values(loops);
118	    vals = g_list_sort(vals, cmp_count_desc);
119	
120	    guint hot = 0;
121	    for (GList *it = vals; it; it = it->next) {
122	        LoopEdge *e = it->data;
123	        if (e->count >= min_iters) {
124	            hot++;
125	        }
126	    }
127	
128	    g_string_append_printf(report,
129	        "hotloops: %u distinct backward edges, %u hot (>= %" PRIu64
130	        " iters), sorted by iterations desc\n",
131	        g_hash_table_size(loops), hot, min_iters);
132	    g_string_append_printf(report, "start_pc, end_pc, iterations\n");
133	
134	    guint64 i = 0;
135	    for (GList *it = vals; it && i < limit; it = it->next) {
136	        LoopEdge *e = it->data;
137	        if (e->count < min_iters) {
138	            continue;
139	        }
140	        g_string_append_printf(report,
141	            "0x%016" PRIx64 ", 0x%016" PRIx64 ", %" PRIu64 "\n",
142	            e->start_pc, e->end_pc, e->count);
143	        i++;
144	    }
145	
146	    qemu_plugin_outs(report->str);
147	
148	    g_list_free(vals);
149	    g_hash_table_destroy(loops);
150	    qemu_plugin_scoreboard_free(vcpu_sb);
151	}
152	
153	QEMU_PLUGIN_EXPORT
154	int qemu_plugin_install(qemu_plugin_id_t id, G_GNUC_UNUSED const qemu_info_t *info,
155	                        int argc, char **argv)
156	{
157	    for (int i = 0; i < argc; i++) {
158	        char *opt = argv[i];
159	        g_auto(GStrv) tok = g_strsplit(opt, "=", 2);
160	        if (g_strcmp0(tok[0], "limit") == 0 && tok[1]) {
161	            limit = g_ascii_strtoull(tok[1], NULL, 0);
162	        } else if (g_strcmp0(tok[0], "min_iters") == 0 && tok[1]) {
163	            min_iters = g_ascii_strtoull(tok[1], NULL, 0);
164	            if (min_iters == 0) {
165	                min_iters = 1;
166	            }
167	        } else {
168	            fprintf(stderr, "hotloops: unknown option: %s\n", opt);
169	            return -1;
170	        }
171	    }
172	
173	    loops = g_hash_table_new_full(loop_hash, loop_equal, NULL, g_free);
174	    vcpu_sb = qemu_plugin_scoreboard_new(sizeof(VCPUState));
175	
176	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
177	    qemu_plugin_register_atexit_cb(id, plugin_exit, NULL);
178	    return 0;
179	}
