// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
// and future backends). One C++20 binary that selects a model (fast / cycle
// / hybrid), resolves engines at runtime, and either passes through to a single
// engine or orchestrates a hybrid round-trip.
//
// This file owns argument dispatch only: parse the CLI, route to a command.
#include <cstdio>
#include <cstdlib>
#include <exception>
#include <string>
#include <string_view>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "log.hpp"

namespace andes_sim {
int cmd_list(const Cli& cli);
int cmd_doctor(const Cli& cli);
int cmd_run(const Cli& cli);
}  // namespace andes_sim

namespace {

using andes_sim::Cli;
using andes_sim::cmd_doctor;
using andes_sim::cmd_list;
using andes_sim::cmd_run;
using andes_sim::is_dev_mode;

// The known command names live in cli.cpp (is_subcommand): the parser needs
// them for the default-command rule, so parse_cli only ever yields run/list/
// doctor (or "" for no args / top-level help). Developer build/test/state-diff
// tooling lives in scripts/, not the binary.

// ---- help model: the user-facing surface rendered as a command tree --------
//
// `run`'s two subcommand groups -- the modes (the composition axis) ...
struct ModeRow {
  const char* name;
  const char* brief;
};
constexpr ModeRow kRunModes[] = {
    {"fast", "QEMU only -- functional, full speed"},
    {"cycle", "one cycle-accurate engine, from reset"},
    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
};

// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
struct TargetRow {
  const char* name;
  const char* brief;
  bool dev;
};
constexpr TargetRow kListTargets[] = {
    {"models", "the modes and their engines", false},
    {"engines", "discovered cycle-accurate engines", false},
    {"fixtures", "internal test ELFs (developer target)", true},
};

// ... and `run`'s options. Each `flag` carries its own leading indent (the pc
// boundaries nest under --trigger pc). `tag` marks a required option (and WHEN
// it is required); `dev` hides it unless ANDESIM_DEV is set.
struct OptRow {
  const char* flag;  // includes its own leading indent
  const char* tag;
  const char* brief;
  bool dev;
};
constexpr OptRow kRunOpts[] = {
    {"  --mode fast|cycle|hybrid", "REQUIRED", "which mode to run", false},
    {"  --trigger marker|pc", "REQUIRED for hybrid", "the ROI delimiter", false},
    {"    --pc-start <sym|0x>", "REQUIRED for --trigger pc", "ROI start boundary", false},
    {"    --pc-end <sym|0x>", "REQUIRED for --trigger pc", "ROI end boundary", false},
    {"  --engine <id>", "", "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)", false},
    {"  --mem-size <spec>", "", "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)", false},
    {"  --dry-run", "", "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)", false},
    {"  --print-memmap", "", "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)", false},
    {"  --verify", "", "cross-check the hybrid run against a QEMU oracle", false},
    {"  --kanata <file>", "", "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)", false},
    {"    --objdump <file>", "", "embed that objdump -d dump's disassembly in the trace (requires --kanata)", false},
    {"  --gdb", "", "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)", false},
    {"  --gdb-port <port>", "", "override the --gdb port (fast 1234, cycle 9104)", false},
    {"  --log-level <0-6>", "", "verbosity, vsim's scale: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off (default 2: program output + the cycle figure)", false},
    {"  --log-file <file>", "", "append EVERY level's messages (timestamped) to <file>; the console keeps --log-level", false},
    {"  -- <args...>", "", "forward everything after -- verbatim to the engine (fast/cycle only; hybrid rejects -- args)", false},
};

// A major command line at column 0: `name   brief`.
void print_major(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "%-7s %s\n", name, brief);
}

// A subcommand/target line, indented two under its command: `  name   brief`.
void print_sub(std::FILE* out, const char* name, const char* brief) {
  std::fprintf(out, "  %-9s %s\n", name, brief);
}

// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
void print_opt(std::FILE* out, const OptRow& o) {
  if (o.tag[0])
    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
  else
    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
}

// `run`: major line, the mode subcommands, then the option list (dev options
// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
void print_run_block(std::FILE* out) {
  print_major(out, "run", "run one simulation (the default: 'run' may be omitted)");
  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
  std::fputs("\n", out);
  for (const OptRow& o : kRunOpts) {
    if (o.dev && !is_dev_mode()) continue;
    print_opt(out, o);
  }
}

void print_list_block(std::FILE* out) {
  print_major(out, "list", "list what is available");
  for (const TargetRow& t : kListTargets) {
    if (t.dev && !is_dev_mode()) continue;
    print_sub(out, t.name, t.brief);
  }
}

void print_doctor_block(std::FILE* out) {
  print_major(out, "doctor", "check toolchain + fixtures are present");
}

// Top-level `andesim --help`: the whole tree -- every major command, its
// subcommands, and run's full option list, so one screen shows everything.
void print_usage(std::FILE* out) {
  std::fputs("usage: andesim [command] [options] <ELF> [-- <engine args>]\n\n",
             out);
  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
             out);
  print_run_block(out);
  std::fputs("\n", out);
  print_list_block(out);
  std::fputs("\n", out);
  print_doctor_block(out);
  std::fputs(
      "\n'andesim run --help' / 'andesim list --help' for per-command "
      "detail.\n",
      out);
}

// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
// parse_cli admits only run/list/doctor, so `run` is the fallthrough.
void print_subcommand_help(std::string_view name, std::FILE* out) {
  if (name == "list") { print_list_block(out); return; }
  if (name == "doctor") { print_doctor_block(out); return; }
  print_run_block(out);
}

}  // namespace

int main(int argc, char** argv) {
  using namespace andes_sim;

  Cli cli = parse_cli(argc, argv);
  if (!cli.error.empty()) {
    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
    return 2;
  }

  if (!set_log_threshold(cli.log_level)) {
    std::fprintf(stderr,
                 "andesim: invalid --log-level '%s' (0=trace 1=debug 2=info "
                 "3=warn 4=error 5=critical 6=off)\n",
                 cli.log_level.c_str());
    return 2;
  }
  if (!set_log_file(cli.log_file)) {
    std::fprintf(stderr, "andesim: cannot open --log-file '%s' for append\n",
                 cli.log_file.c_str());
    return 2;
  }

  if (cli.subcommand.empty()) {  // no command, or top-level -h
    if (cli.help) {
      print_usage(stdout);
      return 0;
    }
    print_usage(stderr);
    return 2;
  }

  if (cli.help) {
    print_subcommand_help(cli.subcommand, stdout);
    return 0;
  }

  if (cli.subcommand == "list") return cmd_list(cli);
  if (cli.subcommand == "doctor") return cmd_doctor(cli);
  return cmd_run(cli);  // parse_cli admits only run/list/doctor
}

// The phase-plan executor (F6) -- there is no QEMU2 handback leg.
// run_plan spawns each leg of a Plan in order,
// threads the drained hybrid_state_v1 file forward (leg N's --handoff-out is
// leg N+1's --resume-from-qemu), and reports each leg's mcycle/minstret.
//
// plan_argvs is the pure core (no spawn, no mmap): it resolves each Step's
// engine + role against the registry and fills the invoke template with the
// threaded state paths, so the argv construction is unit-testable in isolation.
#ifndef ANDESIM_RUN_PLAN_HPP
#define ANDESIM_RUN_PLAN_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "plan.hpp"
#include "process.hpp"

namespace andes_sim {

// The framework-owned values shared by every leg of a run: the resolved
// shared-mmap path/size/base and the QEMU plugin path. Per-leg values
// (bin/state_in/state_out) are derived by plan_argvs from this + the threading.
struct RuntimeCtx {
  std::string mmap_path;
  long long mem_size = 0;
  std::string mmap_base = "0x0";
  std::string plugin_path;
  // QEMU `-readconfig` file matching the accurate engine's ISA, distilled from
  // its config.inc (the engine's `--print-qemu-config`). Empty => the fast leg
  // keeps its descriptor's default `-cpu` (engines without the flag; FA2).
  std::string qemu_cfg;
  // The QEMU CPU model the fast leg must instantiate ({qemu_cpu} fill),
  // parsed from the same probe's `driver = "<cpu>-riscv-cpu"` globals: the
  // readconfig globals only apply to THAT driver, and a mismatched model
  // silently ignores them (found live: andes-ax45mpv kept vlen=512 when the
  // ax66 run asked for 128). Empty => the family default (andes-ax45mpv).
  std::string qemu_cpu;
};

// hw-config sync: the QEMU fast leg models the hardware the accurate-leg
// engine measures, so its -cpu vlen follows that engine's descriptor. 512 is
// the fallback for engines that report none. One definition, used by both the
// plan executor ({vlen} fill) and the hybrid banner.
inline long synced_vlen(long engine_vlen) {
  return engine_vlen > 0 ? engine_vlen : 512;
}

// A trigger's per-leg argv contribution, dispatched by the leg's role. The
// QEMU plugin takes its trigger as a comma-suffix folded INTO the one `-plugin`
// token (so it rides the `{trigger}` placeholder); vsim takes separate tokens
// appended to its argv. marker contributes nothing (plugin/vsim detect the markers
// themselves).
struct LegTriggerArgs {
  std::string plugin_suffix;        // qemu fast-leg: appended to {trigger}
  std::vector<std::string> extra;   // vsim accurate-leg: appended tokens
};

// Map `t` onto `role`'s argv contribution. marker -> empty. pc -> qemu
// `,enter_pc=<enter_pc>` / vsim `--hybrid-exit-pc <exit_pc>`. Roles other
// than fast-leg/accurate-leg get nothing. A missing required param or an
// unknown trigger kind sets `err` (and returns an empty contribution).
//
// NOTE (altitude debt): these flag spellings are framework-side per-engine
// knowledge -- the one place F9 hardcodes a fast/accurate engine's CLI, unlike
// the base argv which comes from each engine's `--describe` invoke template.
// This is a deliberate scope cut: the principled form (per-(trigger,role) argv
// templates carried in `--describe`, filled by build_argv like `invoke`) would
// extend the F2 engine contract and is left for a later feature.
LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
                                std::string& err);

// Turn an accurate engine's `<bin> --print-qemu-config` probe into a QEMU
// `-readconfig` file under `workdir`. On a clean probe (exit 0, non-empty
// stdout) writes `workdir/qemu.cfg` and returns its path; on any failure
// (engine without the flag -> the parser throws -> non-zero exit; timeout;
// spawn failure; empty output; unwritable dir) returns "" -- the tolerant
// fallback that leaves the fast leg on its descriptor's default -cpu.
std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe);

// The QEMU CPU model named by a `--print-qemu-config` probe's text: the first
// `driver = "<cpu>-riscv-cpu"` global, stripped of the "-riscv-cpu" suffix.
// "" when the text names none (probe failed / engine without the hook) -- the
// caller falls back to the family-default -cpu.
std::string qemu_cpu_from_cfg(const std::string& cfg_text);

// Build every step's concrete argv, threading state files under `workdir`:
//   state_in[0]  = ""                       (cold start; no resume)
//   state_in[i]  = state_out[i-1]           (prior leg's drain)
//   state_out[i] = workdir/"state-<i>.bin"  (this leg's drain)
// Each step's engine is looked up in `engines` by id and its `role` template is
// filled via build_argv. Pure (no spawn). Returns one argv per step; on any
// error (unknown engine/role, unresolved placeholder) returns {} and sets `err`.
std::vector<std::vector<std::string>> plan_argvs(
    const Plan& plan, const std::vector<EngineDescriptor>& engines,
    const std::string& workdir, const RuntimeCtx& ctx, std::string& err);

// The exit code a leg returns after draining its state and handing off (the
// driver-side mirror of vsim's kExitHandoffToQemu). Every plan step is a drain
// step, so this is the expected per-leg exit.
constexpr int kDrainRc = 200;

struct PlanOptions {
  int timeout_ms = 90000;     // per-leg spawn timeout
  int expect_rc = kDrainRc;   // drain success code
  std::string plugin_path;    // "" => $VSIM_PLUGIN else repo default
  bool dry_run = false;       // build argvs (incl. qemu_cfg) but spawn nothing
};

// Compose the "plan step N exited wrong" diagnostic. A drain step (expect_rc is
// the handoff/drain code) that exits 0 ran the ELF to completion without ever
// reaching its ROI boundary -- the marker/pc trigger never fired; say so and
// name the trigger kind so the fix (right ELF / right --trigger) is obvious.
// Any other mismatch gets the plain "expected X, got Y" line.
std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
                               int got_rc);

// Execute `plan`: resolve the plugin, acquire the shared mmap (allocate one
// under /dev/shm when plan.mmap_path is empty, and own it), spawn each leg with
// a timeout, require exit == expect_rc, and read back each leg's mcycle/minstret
// from its drained state file. Returns the per-leg results; on the first failure
// `error` describes it and `phases` holds whatever completed before it.
PlanResult run_plan(const Plan& plan,
                    const std::vector<EngineDescriptor>& engines,
                    const PlanOptions& opts = {});

}  // namespace andes_sim

#endif  // ANDESIM_RUN_PLAN_HPP

